#include "k501_aionarc/history.h"
#include "k501_aionarc/bytes.h"
#include "k501_aionarc/sha256.h"
#include <stdlib.h>
#include <string.h>
static const uint8_t DOMAIN[]="K501-CHAIN-2A\0";
bool k501_history_build(uint64_t seq,const k501_object_record_t*r,const qh256_t*state,const uint8_t prev[32],const uint8_t*record_bytes,size_t record_len,k501_history_entry_t*out){uint8_t sb[32];k501_sha256_ctx_t c;if(!r||!state||!prev||!record_bytes||!out)return false;if(!qh256_serialize(state,sb))return false;memset(out,0,sizeof*out);out->sequence=seq;memcpy(out->object_id,r->object_id,32u);memcpy(out->record_hash,r->record_hash,32u);memcpy(out->qh_state,sb,32u);memcpy(out->previous_chain_hash,prev,32u);k501_sha256_init(&c);k501_sha256_update(&c,DOMAIN,sizeof DOMAIN-1u);k501_sha256_update(&c,prev,32u);k501_sha256_update(&c,record_bytes,record_len);k501_sha256_final(&c,out->chain_hash);return true;}
bool k501_history_serialize(const k501_history_entry_t*r,uint8_t**out,size_t*out_len){k501_buf_t b={0};if(!r||!out||!out_len)return false;if(!k501_buf_put(&b,(const uint8_t*)K501_HISTORY_MAGIC,9u)||!k501_buf_put_u64le(&b,r->sequence)||!k501_buf_put(&b,r->object_id,32u)||!k501_buf_put(&b,r->record_hash,32u)||!k501_buf_put(&b,r->qh_state,32u)||!k501_buf_put(&b,r->previous_chain_hash,32u)||!k501_buf_put(&b,r->chain_hash,32u)){k501_buf_free(&b);return false;}*out=b.data;*out_len=b.len;return true;}
bool k501_history_decode(const uint8_t*b,size_t len,k501_history_entry_t*out){size_t p=0u;uint64_t seq;if(!b||!out)return false;if(len<9u+8u+32u*5u)return false;if(memcmp(b,K501_HISTORY_MAGIC,9u)!=0)return false;p=9u;if(!k501_get_u64le(b,len,&p,&seq))return false;out->sequence=seq;if(p+32u*5u>len)return false;memcpy(out->object_id,b+p,32u);p+=32u;memcpy(out->record_hash,b+p,32u);p+=32u;memcpy(out->qh_state,b+p,32u);p+=32u;memcpy(out->previous_chain_hash,b+p,32u);p+=32u;memcpy(out->chain_hash,b+p,32u);p+=32u;return p==len;}
bool k501_history_verify(const k501_history_entry_t*r,const uint8_t*record_bytes,size_t record_len){k501_sha256_ctx_t c;uint8_t h[32];if(!r||!record_bytes)return false;k501_sha256_init(&c);k501_sha256_update(&c,DOMAIN,sizeof DOMAIN-1u);k501_sha256_update(&c,r->previous_chain_hash,32u);k501_sha256_update(&c,record_bytes,record_len);k501_sha256_final(&c,h);return memcmp(h,r->chain_hash,32u)==0;}
